// Catalogue lines of the curiosities added with the "Lire" section: Game of Life, square packing, moving sofa,
// inscribed square, opaque square, equidecomposable polygons, self-similar fractals (issue #36), polyhedra by truncation (issue #35), Viviani's theorem (issue #33), Dandelin's spheres (issue #31), Cavalieri's principle (issue #30), Prince Rupert's cube (issue #27), the star solids and the Wythoff triangle (issue #35), Multibrot and Newton basins, the Apollonian gasket and the 3D escape-time sets (issue #36). Exhibits: gallery/gallery-life.js, gallery/gallery-squares.js, gallery/gallery-sofa.js,
// gallery/gallery-inscribed.js, gallery/gallery-opaque.js, gallery/gallery-equidecomposition.js, gallery/gallery-selfsimilar.js, gallery/gallery-polyhedra.js, gallery/gallery-viviani.js, gallery/gallery-dandelin.js, gallery/gallery-cavalieri.js, gallery/gallery-rupert.js, gallery/gallery-stellation.js, gallery/gallery-wythoff.js, gallery/gallery-basins.js, gallery/gallery-apollonian.js, gallery/gallery-escape3d.js; `links` feed the "À lire aussi" boxes.
const pair=(fr,en)=>[fr,en];
const base={custom:true,symbol:'◇',group:pair('Jeux & histoires','Games & stories'),formula:'',params:[],duration:12,level:pair('Pour tous','For everyone'),
  prereq:pair('De la curiosité. Les explications viennent après la manipulation.','Curiosity. Explanations come after experimenting.'),quizState:{}};
export const CURIOSITIES=[
  {...base,id:'life',title:pair('Le jeu de la vie','The Game of Life'),short:pair('Jeu de la vie de Conway','Conway’s Game of Life'),
    intro:pair('Une grille, deux règles, aucune intervention : des formes clignotent, voyagent, se multiplient ou meurent.','A grid, two rules, no intervention: shapes blink, travel, multiply or die.'),
    steps:[pair('Lance le planeur et compte les générations avant qu’il retrouve sa forme.','Play the glider and count the generations before it takes its shape again.'),pair('Dessine trois cases alignées, puis un carré de quatre cases. Lesquelles bougent ?','Draw three cells in a row, then a block of four. Which ones move?'),pair('Lance le R-pentomino : cinq cases seulement. Prédis ce qui va se passer avant de regarder.','Play the R-pentomino: only five cells. Predict what will happen before you watch.')],
    quiz:pair('Un planeur reprend sa forme, décalé d’une case en diagonale, au bout de combien de générations ?','A glider takes its shape again, shifted one cell diagonally, after how many generations?'),answer:4,
    explain:pair('Après 4 générations, le planeur a la même forme, décalé d’une case vers la droite et d’une vers le bas : il avance d’une case toutes les 4 générations.','After 4 generations the glider has the same shape, shifted one cell right and one cell down: it travels one cell every 4 generations.'),
    history:pair('Conway · 1970','Conway · 1970'),
    story:pair('John Horton Conway cherchait une règle très simple dont l’évolution reste imprévisible. Martin Gardner la présente en octobre 1970 dans sa rubrique de Scientific American ; des lecteurs du monde entier envoient leurs découvertes, dont le canon à planeurs de Bill Gosper la même année. L’idée d’automate cellulaire remonte à John von Neumann et Stanislaw Ulam, qui cherchaient une machine capable de se reproduire.','John Horton Conway was looking for a very simple rule whose evolution stays unpredictable. Martin Gardner presented it in October 1970 in his Scientific American column; readers worldwide sent in their discoveries, among them Bill Gosper’s glider gun that same year. The idea of a cellular automaton goes back to John von Neumann and Stanislaw Ulam, who were looking for a machine able to reproduce itself.'),
    source:'https://mathshistory.st-andrews.ac.uk/Biographies/Conway/',sourceLabel:pair('Conway · MacTutor (anglais)','Conway · MacTutor'),
    reasoning:{conjecture:pair('Une configuration finie peut disparaître, se figer, osciller, voyager ou grandir sans limite.','A finite pattern can die out, freeze, oscillate, travel or grow without bound.'),
      proof:pair('Chaque case ne dépend que de ses huit voisines, donc l’évolution d’un motif isolé ne dépend que de lui. Pour un oscillateur ou un vaisseau, il suffit de calculer une période : si le motif revient à sa forme, il recommencera indéfiniment. Le canon montre qu’une croissance illimitée est possible : il revient à sa forme toutes les 30 générations en ayant émis un planeur.','Each cell depends only on its eight neighbours, so an isolated pattern evolves on its own. For an oscillator or a spaceship it is enough to compute one period: once the pattern takes its shape again, it will repeat forever. The gun shows that unbounded growth is possible: it takes its shape again every 30 generations, having fired one glider.'),
      transfer:pair('À tester : deux planeurs qui se croisent. Que reste-t-il après la collision ?','Try two gliders that meet. What is left after the collision?')},
    links:['#biographies/von-neumann']},
  {...base,id:'square-packing',title:pair('Des carrés dans un carré','Squares in a square'),short:pair('Empilement de carrés','Square packing'),
    intro:pair('Range des carrés de côté 1 dans le plus petit carré possible. Parfois, tourner un carré fait gagner de la place.','Fit squares of side 1 into the smallest possible square. Sometimes turning a square saves room.'),
    steps:[pair('Avec 5 carrés, essaie de faire mieux que le côté 3 sans rien tourner. Puis tourne un carré.','With 5 squares, try to beat side 3 without turning anything. Then turn one square.'),pair('Affiche la meilleure disposition connue pour 5, puis pour 10. Quel lien vois-tu ?','Show the best known packing for 5, then for 10. What link do you see?'),pair('Essaie 11 carrés : approche-toi du record de 3,877.','Try 11 squares: get close to the record of 3.877.')],
    quiz:pair('Combien de carrés de côté 1, au plus, peut-on ranger sans chevauchement dans un carré de côté 2,7 ?','At most how many squares of side 1 can be fitted without overlap into a square of side 2.7?'),answer:4,
    explain:pair('Quatre carrés tiennent dans un carré de côté 2. Pour cinq, il faut un côté d’au moins 2 + 1/√2 ≈ 2,707 (Göbel, 1979), plus que 2,7. Donc 4.','Four squares fit in a square of side 2. Five need side at least 2 + 1/√2 ≈ 2.707 (Göbel, 1979), more than 2.7. So 4.'),
    history:pair('Erdős et Graham · 1975','Erdős and Graham · 1975'),
    story:pair('Le problème a été étudié par Paul Erdős et Ronald Graham en 1975, qui se demandaient combien de place on perd quand le grand carré n’a pas un côté entier. Depuis, chercheurs et amateurs améliorent les records un par un ; Erich Friedman tient à jour la liste des meilleures dispositions connues.','Paul Erdős and Ronald Graham studied the problem in 1975, asking how much room is wasted when the big square does not have a whole-number side. Since then researchers and amateurs have improved the records one by one; Erich Friedman keeps the list of best known packings up to date.'),
    source:'https://www.combinatorics.org/ojs/index.php/eljc/article/view/DS7',sourceLabel:pair('E. Friedman, Packing Unit Squares in Squares · Electronic Journal of Combinatorics (anglais)','E. Friedman, Packing Unit Squares in Squares · Electronic Journal of Combinatorics'),
    reasoning:{conjecture:pair('Pour n carrés, il faut un côté d’au moins √n ; quand n est un carré parfait, la grille est optimale.','n squares need a side of at least √n; when n is a perfect square, the grid is optimal.'),
      proof:pair('L’aire du grand carré doit dépasser la somme des aires, n, donc son côté est au moins √n. Ce minorant est atteint par la grille quand n = k². Pour les autres n, il n’est pas atteint et l’on ne connaît le côté optimal que dans quelques cas, chacun demandant sa propre démonstration.','The area of the big square must be at least the total area n, so its side is at least √n. This bound is reached by the grid when n = k². For other n it is not reached, and the optimal side is known only in a few cases, each needing its own proof.'),
      transfer:pair('À discuter : pourquoi la disposition de 10 carrés montre-t-elle que 3 + 1/√2 suffit ?','Discuss: why does the 10-square packing show that 3 + 1/√2 is enough?')},
    links:['#biographies/erdos']},
  {...base,id:'moving-sofa',title:pair('Le canapé dans le couloir','The moving sofa'),short:pair('Problème du canapé','Moving sofa problem'),
    intro:pair('Quel est le plus grand canapé qu’on peut faire passer dans un couloir de largeur 1 qui tourne à angle droit ?','What is the largest sofa that can be moved along a hallway of width 1 with a right-angled turn?'),
    steps:[pair('Essaie un rectangle de largeur 1, puis allonge-le. À partir de quand reste-t-il coincé ?','Try a rectangle of width 1, then make it longer. From when does it get stuck?'),pair('Choisis la famille de Hammersley avec r = 0, puis augmente r. L’aire monte-t-elle toujours ?','Choose Hammersley’s family with r = 0, then increase r. Does the area always go up?'),pair('Choisis le canapé de Gerver et fais-le passer toi-même, puis dessine ton propre canapé.','Choose Gerver’s sofa and take it round the corner yourself, then draw your own sofa.')],
    quiz:pair('Quelle est la plus grande aire d’un canapé qui passe le coin d’un couloir de largeur 1 ?','What is the largest area of a sofa that can go round the corner of a hallway of width 1?'),
    explain:pair('Un demi-disque de rayon 1 passe en tournant sur place : aire π/2 ≈ 1,57. Hammersley (1968) fait mieux en coupant ce demi-disque en deux et en insérant entre les moitiés un bloc creusé d’un demi-cercle : aire π/2 + 2/π ≈ 2,2074. Gerver (1992) arrondit encore les bords : aire ≈ 2,2195. Personne n’a trouvé mieux, et en 2024 Jineon Baek a annoncé une démonstration que c’est le maximum ; elle est en cours de vérification. La réponse la plus probable est donc environ 2,2195, sans formule simple.','A half-disc of radius 1 gets through by turning on the spot: area π/2 ≈ 1.57. Hammersley (1968) does better by cutting this half-disc in two and inserting between the halves a block hollowed out by a half-circle: area π/2 + 2/π ≈ 2.2074. Gerver (1992) rounds the edges further: area ≈ 2.2195. Nobody has found better, and in 2024 Jineon Baek announced a proof that this is the maximum; it is being checked. So the most likely answer is about 2.2195, with no simple formula.'),
    history:pair('Moser · 1966','Moser · 1966'),
    story:pair('Leo Moser pose le problème en 1966. John Hammersley trouve en 1968 un canapé d’aire π/2 + 2/π et montre qu’on ne peut pas dépasser 2√2. Joseph Gerver propose en 1992 une forme un peu plus grande, d’aire environ 2,2195. En 2024, Jineon Baek annonce une démonstration que le canapé de Gerver est optimal ; au 20 octobre 2026, elle n’est pas encore publiée dans une revue et reste en cours de vérification.','Leo Moser posed the problem in 1966. John Hammersley found in 1968 a sofa of area π/2 + 2/π and showed that 2√2 cannot be exceeded. Joseph Gerver proposed in 1992 a slightly larger shape, of area about 2.2195. In 2024 Jineon Baek announced a proof that Gerver’s sofa is optimal; as of 20 October 2026 it has not yet appeared in a journal and is still being checked.'),
    source:'https://arxiv.org/abs/2411.19826',sourceLabel:pair('J. Baek, Optimality of Gerver’s sofa · arXiv (anglais)','J. Baek, Optimality of Gerver’s sofa · arXiv'),
    reasoning:{conjecture:pair('Dans la famille de Hammersley, l’aire est la plus grande pour r = 2/π, et chaque canapé de la famille passe le coin.','In Hammersley’s family the area is largest for r = 2/π, and every sofa of the family goes round the corner.'),
      proof:pair('Le canapé est formé de deux quarts de disque (aire π/2 en tout) et d’un rectangle 2r × 1 privé d’un demi-disque de rayon r : A(r) = π/2 + 2r − πr²/2. A′(r) = 2 − πr s’annule pour r = 2/π, où A est maximale. Pour tourner, le canapé pivote d’un quart de tour pendant que le centre de l’encoche parcourt le cercle de rayon r autour du coin intérieur : le coin reste dans l’encoche, les quarts de disque restent contre les murs extérieurs.','The sofa is made of two quarter discs (area π/2 in all) and a 2r × 1 rectangle minus a half disc of radius r: A(r) = π/2 + 2r − πr²/2. A′(r) = 2 − πr vanishes at r = 2/π, where A is largest. To turn, the sofa rotates a quarter turn while the centre of the notch runs round the circle of radius r about the inner corner: the corner stays in the notch, the quarter discs stay against the outer walls.'),
      transfer:pair('À discuter : pourquoi un canapé plus large que le couloir ne peut-il jamais passer, quelle que soit sa forme ?','Discuss: why can a sofa wider than the hallway never pass, whatever its shape?')},
    links:[]},
  {...base,id:'inscribed-square',title:pair('Un carré sur chaque courbe ?','A square on every curve?'),short:pair('Problème du carré inscrit','Inscribed square problem'),
    intro:pair('Dessine n’importe quelle courbe fermée : on y trouve quatre points qui forment un carré. Toujours ? Personne ne le sait.','Draw any closed curve: four of its points form a square. Always? Nobody knows.'),
    steps:[pair('Compare le triangle acutangle et le triangle obtusangle : combien de carrés chacun contient-il ?','Compare the acute and the obtuse triangle: how many squares does each contain?'),pair('Dessine une courbe très tordue. La recherche trouve-t-elle encore un carré ?','Draw a very twisted curve. Does the search still find a square?'),pair('Règle le rapport des côtés sur 2 : cherche des rectangles deux fois plus longs que larges.','Set the ratio of the sides to 2: look for rectangles twice as long as they are wide.')],
    quiz:pair('Combien de carrés inscrits (quatre sommets sur le bord) contient un triangle dont les trois angles sont aigus ?','How many inscribed squares (four corners on the boundary) does a triangle with three acute angles contain?'),answer:3,
    explain:pair('Quatre sommets sur trois côtés : deux sont sur le même côté, donc le carré a un côté posé sur un côté du triangle. Sur la base a de hauteur h, le carré de côté s = ah/(a + h) tient si le pied de la hauteur tombe dans la base, ce qui arrive pour les trois côtés quand les trois angles sont aigus.','Four corners on three sides: two lie on the same side, so the square has a side lying on a side of the triangle. On base a with height h, the square of side s = ah/(a + h) fits when the foot of the height falls inside the base, which happens for all three sides when the three angles are acute.'),
    history:pair('Toeplitz · 1911','Toeplitz · 1911'),
    story:pair('Otto Toeplitz pose la question en 1911. Arnold Emch la résout pour les courbes convexes en 1913, Lev Schnirelmann pour les courbes lisses en 1929. Pour une courbe continue quelconque, qui peut zigzaguer à toutes les échelles, le problème est toujours ouvert. En 2020, Joshua Greene et Andrew Lobb montrent que toute courbe lisse contient des rectangles inscrits de toutes les formes.','Otto Toeplitz asked the question in 1911. Arnold Emch solved it for convex curves in 1913, Lev Schnirelmann for smooth curves in 1929. For an arbitrary continuous curve, which may zigzag at every scale, the problem is still open. In 2020 Joshua Greene and Andrew Lobb showed that every smooth curve contains inscribed rectangles of every shape.'),
    source:'https://arxiv.org/abs/2005.09193',sourceLabel:pair('J. Greene et A. Lobb, The rectangular peg problem · arXiv (anglais)','J. Greene and A. Lobb, The rectangular peg problem · arXiv'),
    reasoning:{conjecture:pair('Toute courbe fermée qui ne se croise pas contient quatre points formant un carré.','Every closed curve that does not cross itself contains four points forming a square.'),
      proof:pair('Démontré pour les courbes convexes, lisses ou polygonales régulières, ouvert en général. Pour les triangles, on peut tout compter : un carré inscrit a un côté sur un côté du triangle (deux de ses sommets sont sur le même côté), et le théorème de Thalès donne son côté ah/(a + h).','Proved for convex, smooth or well-behaved curves, open in general. For triangles everything can be counted: an inscribed square has a side on a side of the triangle (two of its corners lie on the same side), and similar triangles give its side ah/(a + h).'),
      transfer:pair('À tester : un cercle contient une infinité de carrés inscrits. Une ellipse en contient-elle plusieurs ?','Try it: a circle contains infinitely many inscribed squares. Does an ellipse contain several?')},
    links:[]},
  {...base,id:'opaque-square',title:pair('Le carré opaque','The opaque square'),short:pair('Problème du carré opaque','Opaque square problem'),
    intro:pair('Construis le mur le plus court possible pour que personne ne puisse voir à travers un carré, dans aucune direction.','Build the shortest possible wall so that nobody can see through a square, in any direction.'),
    steps:[pair('Supprime un côté de la barrière « trois côtés » : trouve une direction où la lumière passe.','Remove one side of the “three sides” barrier: find a direction where light gets through.'),pair('Compare les diagonales et l’arbre de Steiner. Lequel est le plus court ?','Compare the diagonals and the Steiner tree. Which is shorter?'),pair('Pars de rien et construis ta barrière. Peux-tu descendre sous 2,7 ?','Start from nothing and build your barrier. Can you go below 2.7?')],
    quiz:pair('Parmi les quatre côtés d’un carré, combien faut-il en garder, au minimum, pour qu’aucune droite ne traverse le carré sans les rencontrer ?','Of the four sides of a square, at least how many must be kept so that no line crosses the square without meeting them?'),answer:3,
    explain:pair('Avec deux côtés opposés, les droites parallèles à ces côtés passent entre eux. Avec deux côtés voisins, une droite qui coupe les deux autres côtés près du coin opposé passe sans les toucher. Trois côtés suffisent : une droite qui traverse le carré coupe son bord en deux points, et au plus un est sur le côté manquant.','With two opposite sides, the lines parallel to them pass between them. With two neighbouring sides, a line cutting the other two sides near the opposite corner passes without touching them. Three sides are enough: a line crossing the square meets its boundary in two points, at most one of them on the missing side.'),
    history:pair('Mazurkiewicz · 1916','Mazurkiewicz · 1916'),
    story:pair('Stefan Mazurkiewicz introduit les ensembles opaques en 1916 ; Frederick Bagemihl pose en 1959 la question de leur longueur minimale. Pour le carré, la meilleure barrière connue mesure √2 + √6/2 ≈ 2,639. Le minorant 2 date de 1964 ; il n’a été amélioré qu’en 2019, à 2,00002.','Stefan Mazurkiewicz introduced opaque sets in 1916; Frederick Bagemihl asked for their least length in 1959. For the square, the best known barrier has length √2 + √6/2 ≈ 2.639. The lower bound 2 dates from 1964; it was only improved in 2019, to 2.00002.'),
    source:'https://arxiv.org/abs/1311.3323',sourceLabel:pair('A. Dumitrescu et M. Jiang, The opaque square · arXiv (anglais)','A. Dumitrescu and M. Jiang, The opaque square · arXiv'),
    reasoning:{conjecture:pair('Toute barrière opaque du carré de côté 1 mesure au moins 2.','Every opaque barrier of the unit square has length at least 2.'),
      proof:pair('Dans chaque direction, l’ombre des segments doit recouvrir l’ombre du carré : la somme de leurs projections dépasse la largeur du carré dans cette direction. Faisons la moyenne sur toutes les directions : un segment de longueur ℓ a une projection moyenne 2ℓ/π, et le carré une largeur moyenne égale à son périmètre divisé par π, soit 4/π (formule de Cauchy). Donc 2L/π ≥ 4/π, c’est-à-dire L ≥ 2.','In every direction the shadow of the segments must cover the shadow of the square: the sum of their projections exceeds the width of the square in that direction. Average over all directions: a segment of length ℓ has mean projection 2ℓ/π, and the square has mean width equal to its perimeter divided by π, that is 4/π (Cauchy’s formula). So 2L/π ≥ 4/π, that is L ≥ 2.'),
      transfer:pair('À discuter : la meilleure barrière connue n’est pas d’un seul tenant. Pourquoi un morceau détaché peut-il aider ?','Discuss: the best known barrier is not in one piece. Why can a detached piece help?')},
    links:[]},
  {...base,id:'equidecomposition',title:pair('Découper et recoller des polygones','Cutting and regluing polygons'),short:pair('Équidécoupage des polygones','Polygon equidecomposition'),
    intro:pair('Deux polygones de même aire : on peut toujours découper l’un en morceaux qui se recollent en l’autre, sans les retourner.','Two polygons of the same area: one can always be cut into pieces that reglue into the other, without flipping them.'),
    steps:[pair('Lance l’exemple « Carré → Triangle » et suis chaque étape : où passent les morceaux ?','Play the example “Square → Triangle” and follow each step: where do the pieces go?'),pair('Choisis une croix et une flèche, puis avance à la main avec le curseur. Combien de morceaux faut-il à l’étape 1 ?','Choose a cross and an arrow, then move by hand with the slider. How many pieces does step 1 need?'),pair('Dessine ton propre polygone, ou écris ses sommets au clavier, et regarde-le devenir un carré.','Draw your own polygon, or type its vertices, and watch it become a square.')],
    quiz:pair('Deux polygones ont la même aire. Peut-on toujours découper le premier en un nombre fini de morceaux qui, recollés autrement, forment exactement le second ?','Two polygons have the same area. Can the first always be cut into finitely many pieces which, put together differently, form exactly the second?'),
    explain:pair('Oui (théorème de Wallace, Bolyai et Gerwien). On découpe chaque polygone en triangles. Chaque triangle se découpe en un rectangle : on coupe à mi-hauteur et on fait pivoter les deux coins. Chaque rectangle se découpe en un rectangle de largeur 1, de même aire. On empile ces rectangles : les deux polygones donnent le même grand rectangle de largeur 1. Il suffit alors de suivre le chemin du premier polygone vers ce rectangle, puis celui du second à l’envers. En dimension 3, c’est faux : Dehn a montré en 1900 qu’un cube et un tétraèdre régulier de même volume ne se découpent pas l’un en l’autre.','Yes (theorem of Wallace, Bolyai and Gerwien). Cut each polygon into triangles. Each triangle can be cut into a rectangle: cut at half height and swing the two corners round. Each rectangle can be cut into a rectangle of width 1 with the same area. Stack those rectangles: both polygons give the same big rectangle of width 1. Then follow the first polygon’s path to that rectangle, and the second one’s path backwards. In three dimensions it is false: in 1900 Dehn showed that a cube and a regular tetrahedron of the same volume cannot be cut into each other.'),
    history:pair('Wallace, Bolyai, Gerwien · 1807 à 1833','Wallace, Bolyai, Gerwien · 1807 to 1833'),
    story:pair('William Wallace énonce le résultat en 1807 ; Farkas Bolyai en 1832 et Paul Gerwien en 1833 en donnent chacun une démonstration, d’où le nom du théorème. En 1900, David Hilbert demande si le même énoncé vaut pour les polyèdres (troisième problème) ; son élève Max Dehn répond par la négative la même année : un cube et un tétraèdre régulier de même volume ne sont pas équidécomposables.','William Wallace stated the result in 1807; Farkas Bolyai in 1832 and Paul Gerwien in 1833 each gave a proof, hence the name of the theorem. In 1900 David Hilbert asked whether the same statement holds for polyhedra (third problem); his student Max Dehn answered no that same year: a cube and a regular tetrahedron of equal volume are not equidecomposable.'),
    source:'https://en.wikipedia.org/wiki/Wallace%E2%80%93Bolyai%E2%80%93Gerwien_theorem',sourceLabel:pair('Théorème de Wallace-Bolyai-Gerwien · Wikipédia (anglais)','Wallace-Bolyai-Gerwien theorem · Wikipedia'),
    reasoning:{conjecture:pair('Deux polygones simples de même aire sont équidécomposables : l’un se découpe en un nombre fini de polygones qui, par rotations et translations, se recollent en l’autre.','Two simple polygons of the same area are equidecomposable: one is cut into finitely many polygons that, by rotations and translations, reglue into the other.'),
      proof:pair('La condition est nécessaire, car les déplacements conservent l’aire. Elle est suffisante : on triangule P, on transforme chaque triangle en rectangle (trois morceaux), chaque rectangle en rectangle de largeur W fixée (deux cisaillements par bandes), puis on empile ces rectangles en un rectangle R de dimensions W × A/W. Même chose pour Q ; il suffit de jouer la deuxième chaîne à l’envers.','The condition is necessary, since moves keep the area. It is sufficient: triangulate P, turn each triangle into a rectangle (three pieces), each rectangle into a rectangle of a fixed width W (two shears by strips), then stack these rectangles into a rectangle R of size W × A/W. Do the same for Q and play the second chain backwards.'),
      transfer:pair('À discuter : le cube et le tétraèdre régulier de même volume ne sont pas équidécomposables (Dehn, 1900). Qu’est-ce qui, dans la preuve du plan, ne se transporte pas à l’espace ?','Discuss: a cube and a regular tetrahedron of equal volume are not equidecomposable (Dehn, 1900). What in the proof for the plane does not carry over to space?')},
    links:['#lab/tiles','#gallery/banach-tarski-gallery','#lab/banach-tarski-model','#history/advances/banach-tarski']},
  {...base,id:'self-similar',symbol:'❋',group:pair('Formes & mouvement','Shapes & motion'),level:pair('Seconde · Terminale','Grades 10 to 12'),
    prereq:pair('Puissances, suites géométriques ; le logarithme pour la dimension (Terminale).','Powers, geometric sequences; the logarithm for the dimension (grade 12).'),
    title:pair('Fractales, étape par étape','Fractals, stage by stage'),short:pair('Cantor, Koch, Sierpiński, Menger','Cantor, Koch, Sierpiński, Menger'),
    intro:pair('Une règle simple, répétée sans fin : enlever, ajouter, recommencer. Construis cinq fractales étape par étape, compte les morceaux, suis la longueur, l’aire ou le volume, et découvre une dimension qui n’est pas un nombre entier.','One simple rule, repeated forever: remove, add, repeat. Build five fractals stage by stage, count the pieces, follow the length, area or volume, and discover a dimension that is not a whole number.'),
    steps:[pair('Choisis l’éponge de Menger. Avant d’avancer, réponds à la prédiction : le volume finit-il par disparaître ?','Choose the Menger sponge. Before going on, answer the prediction: does the volume vanish in the end?'),pair('Avance d’une étape à la fois et lis le nombre de cubes et le volume gardé. Quelle suite reconnais-tu ?','Go one stage at a time and read the number of cubes and the volume kept. Which sequence do you recognise?'),pair('Compare avec le flocon de Koch : le périmètre explose, mais l’aire reste bornée. Puis lis la dimension de chaque figure et place-la entre 0, 1, 2 et 3.','Compare with the Koch snowflake: the perimeter blows up, but the area stays bounded. Then read the dimension of each figure and place it between 0, 1, 2 and 3.')],
    quiz:pair('À l’étape 2 de l’éponge de Menger, combien reste-t-il de petits cubes ?','At stage 2 of the Menger sponge, how many small cubes are left?'),answer:400,
    explain:pair('Chaque cube est remplacé par 20 cubes trois fois plus petits (on en enlève 7 sur 27). Après deux étapes : 20 × 20 = 400 cubes, chacun de côté 1/9. Le volume gardé est 400/729 = (20/27)², environ 0,549 : une suite géométrique de raison 20/27 < 1, donc il tend vers 0. L’éponge limite a un volume nul, mais elle n’est pas vide : elle contient par exemple toutes les arêtes du cube de départ. Sa dimension est log 20 / log 3 ≈ 2,727.','Each cube is replaced by 20 cubes three times smaller (7 out of 27 are removed). After two stages: 20 × 20 = 400 cubes, each of side 1/9. The volume kept is 400/729 = (20/27)², about 0.549: a geometric sequence with ratio 20/27 < 1, so it tends to 0. The limit sponge has zero volume, but it is not empty: it contains for example every edge of the original cube. Its dimension is log 20 / log 3 ≈ 2.727.'),
    history:pair('Cantor 1883 · Koch 1904 · Sierpiński 1916 · Menger 1926','Cantor 1883 · Koch 1904 · Sierpiński 1916 · Menger 1926'),
    story:pair('Georg Cantor décrit en 1883 l’ensemble qui porte son nom ; Helge von Koch publie en 1904 une courbe continue sans tangente en aucun point ; Wacław Sierpiński présente son tapis en 1916 ; Karl Menger construit son éponge en 1926 dans ses travaux sur la dimension. Le mot « fractale » est forgé par Benoît Mandelbrot en 1975. Les dimensions affichées sont celles de la figure limite, obtenues par un théorème ; une étape finie n’en est qu’une approximation.','Georg Cantor described the set named after him in 1883; Helge von Koch published in 1904 a continuous curve with no tangent at any point; Wacław Sierpiński presented his carpet in 1916; Karl Menger built his sponge in 1926 in his work on dimension. The word “fractal” was coined by Benoît Mandelbrot in 1975. The dimensions shown are those of the limit figure, given by a theorem; a finite stage is only an approximation of it.'),
    source:'https://mathworld.wolfram.com/MengerSponge.html',sourceLabel:pair('Menger Sponge · MathWorld (anglais)','Menger Sponge · MathWorld'),
    reasoning:{conjecture:pair('Un objet qui garde de plus en plus de morceaux garde aussi du volume.','An object that keeps more and more pieces also keeps some volume.'),
      proof:pair('Faux. À l’étape n il y a 20ⁿ cubes de volume (1/27)ⁿ, soit un volume (20/27)ⁿ qui tend vers 0 : le nombre de morceaux croît, mais moins vite que leur taille ne diminue. La dimension D = log 20 / log 3 vient de N = (1/r)^D ; le théorème de Moran et Hutchinson assure que c’est la dimension de Hausdorff quand les copies ne se chevauchent pas, ce qui est le cas ici.','False. At stage n there are 20ⁿ cubes of volume (1/27)ⁿ, a volume (20/27)ⁿ that tends to 0: the number of pieces grows, but more slowly than their size shrinks. The dimension D = log 20 / log 3 comes from N = (1/r)^D; the theorem of Moran and Hutchinson makes it the Hausdorff dimension when the copies do not overlap, as here.'),
      transfer:pair('À calculer : le tétraèdre de Sierpiński garde 4 copies de moitié taille. Quel volume à l’étape 5, et quelle dimension ? ((1/2)⁵ = 1/32 ; log 4 / log 2 = 2.)','Compute: the Sierpiński tetrahedron keeps 4 half-size copies. What volume at stage 5, and what dimension? ((1/2)⁵ = 1/32; log 4 / log 2 = 2.)')},
    links:['#gallery/mandelbrot','#gallery/chaos','#chapter/terminale-01','#chapter/terminale-08']},
  {...base,id:'polyhedra',symbol:'⬡',group:pair('Formes & mouvement','Shapes & motion'),level:pair('Seconde · Terminale','Grades 10 to 12'),
    prereq:pair('Solides usuels, polygones réguliers ; dénombrer avec soin.','Usual solids, regular polygons; careful counting.'),
    title:pair('Couper les coins d’un polyèdre','Cutting the corners of a polyhedron'),short:pair('Troncature et dualité des polyèdres','Truncation and duality of polyhedra'),
    intro:pair('Prends un cube et coupe ses huit coins, de plus en plus profondément. Il passe par le cube tronqué, le cuboctaèdre, l’octaèdre tronqué… et finit sur un autre solide de Platon. Lequel, et pourquoi ?','Take a cube and cut its eight corners, deeper and deeper. It goes through the truncated cube, the cuboctahedron, the truncated octahedron… and ends on another Platonic solid. Which one, and why?'),
    steps:[pair('Réponds à la question, puis fais glisser la profondeur jusqu’au bout.','Answer the question, then slide the depth all the way.'),pair('Arrête-toi sur chaque solide nommé : compte les faces de chaque sorte et vérifie V − E + F.','Stop on each named solid: count the faces of each kind and check V − E + F.'),pair('Montre le dual en pointillés : à quel moment les coupes deviennent-elles ses faces ? Recommence avec le dodécaèdre.','Show the dual, dotted: when do the cuts become its faces? Start again from the dodecahedron.')],
    quiz:pair('Un ballon de football a la forme d’un icosaèdre tronqué (12 pentagones et 20 hexagones). Combien a-t-il de sommets ?','A football has the shape of a truncated icosahedron (12 pentagons and 20 hexagons). How many vertices does it have?'),answer:60,
    explain:pair('60 sommets. Chacun des 12 sommets de l’icosaèdre est coupé et devient un pentagone de 5 sommets : 12 × 5 = 60. On le vérifie autrement : 12 pentagones et 20 hexagones ont 12 × 5 + 20 × 6 = 180 côtés, chaque arête est partagée par 2 faces, donc E = 90 ; chaque sommet touche 3 faces, donc V = 180 / 3 = 60 ; et 60 − 90 + 32 = 2.','60 vertices. Each of the 12 vertices of the icosahedron is cut off and becomes a pentagon with 5 vertices: 12 × 5 = 60. Another check: 12 pentagons and 20 hexagons have 12 × 5 + 20 × 6 = 180 sides, each edge is shared by 2 faces, so E = 90; each vertex touches 3 faces, so V = 180 / 3 = 60; and 60 − 90 + 32 = 2.'),
    history:pair('Archimède · Kepler 1619','Archimedes · Kepler 1619'),
    story:pair('Archimède a décrit treize solides à faces régulières, d’après Pappus ; son texte est perdu. Kepler les a retrouvés et dessinés dans « Harmonices Mundi » (1619), où il nomme aussi le cuboctaèdre et l’icosidodécaèdre. La dualité, qui échange sommets et faces, relie chaque solide de Platon à un autre : le cube à l’octaèdre, le dodécaèdre à l’icosaèdre, le tétraèdre à lui-même.','Archimedes described thirteen solids with regular faces, according to Pappus; his text is lost. Kepler rediscovered and drew them in “Harmonices Mundi” (1619), where he also named the cuboctahedron and the icosidodecahedron. Duality, which swaps vertices and faces, links each Platonic solid to another: the cube to the octahedron, the dodecahedron to the icosahedron, the tetrahedron to itself.'),
    source:'https://mathworld.wolfram.com/ArchimedeanSolid.html',sourceLabel:pair('Archimedean Solid · MathWorld (anglais)','Archimedean Solid · MathWorld'),
    reasoning:{conjecture:pair('Si l’on coupe les coins d’un cube jusqu’au bout, il reste un cube plus petit.','If the corners of a cube are cut all the way, a smaller cube is left.'),
      proof:pair('Faux. Les plans de coupe sont perpendiculaires aux directions des 8 sommets : ce sont les plans des 8 faces d’un octaèdre. Quand ils coupent assez profond, les 6 faces du cube ne touchent plus le solide qu’en un point chacune, et il reste exactement l’octaèdre : les 6 faces sont devenues 6 sommets, les 8 sommets 8 faces. La vérification par le calcul est faite pour chaque profondeur : V − E + F = 2, et les nombres aux arrêts nommés sont ceux des tables (MathWorld).','False. The cutting planes are perpendicular to the directions of the 8 vertices: they are the planes of the 8 faces of an octahedron. When they cut deep enough, each of the 6 faces of the cube touches the solid in a single point, and exactly the octahedron is left: the 6 faces became 6 vertices, the 8 vertices 8 faces. The computation is checked at every depth: V − E + F = 2, and the counts at the named stops are those of the tables (MathWorld).'),
      transfer:pair('À calculer : le dodécaèdre tronqué (on coupe les 20 sommets du dodécaèdre). Combien de sommets, d’arêtes, de faces ? (60, 90, 32 : 20 triangles et 12 décagones.)','Compute: the truncated dodecahedron (cut the 20 vertices of the dodecahedron). How many vertices, edges, faces? (60, 90, 32: 20 triangles and 12 decagons.)')},
    links:['#gallery/platonic','#chapter/terminale-02']},
  {...base,id:'viviani',symbol:'△',group:pair('Formes & mouvement','Shapes & motion'),level:pair('Seconde','Grade 10'),
    prereq:pair('Aire d’un triangle (base × hauteur ÷ 2), distance d’un point à une droite.','Area of a triangle (base × height ÷ 2), distance from a point to a line.'),
    title:pair('Le point qui ne change rien','The point that changes nothing'),short:pair('Théorème de Viviani','Viviani’s theorem'),
    intro:pair('Dans un triangle équilatéral, place un point où tu veux et mesure ses distances aux trois côtés. Additionne-les. Recommence ailleurs. Que se passe-t-il ?','In an equilateral triangle, put a point anywhere and measure its distances to the three sides. Add them up. Start again somewhere else. What happens?'),
    steps:[pair('Réponds à la question, puis promène P : au centre, contre un côté, dans un coin.','Answer the question, then move P around: at the centre, against a side, in a corner.'),pair('Agrandis ou tourne le triangle par un sommet : la somme change-t-elle ? À quoi la comparer ?','Enlarge or turn the triangle by a vertex: does the sum change? What should it be compared with?'),pair('Ouvre « Voir les trois triangles », puis passe en triangle quelconque : qu’est-ce qui reste vrai ?','Open “Show the three triangles”, then switch to any triangle: what stays true?')],
    quiz:pair('Un triangle équilatéral a pour côté 6. Un point P à l’intérieur est à la distance 1 d’un côté et 2 d’un autre. Quelle est sa distance au troisième côté (arrondie au centième) ?','An equilateral triangle has side 6. A point P inside is at distance 1 from one side and 2 from another. What is its distance to the third side (to the nearest hundredth)?'),answer:2.2,tolerance:0.006,
    explain:pair('La somme des trois distances vaut la hauteur h = 6 × √3 ÷ 2 = 3√3 ≈ 5,196. La troisième distance est donc 3√3 − 1 − 2 ≈ 2,20. Pourquoi la somme vaut h : en reliant P aux sommets, on coupe le triangle en trois triangles de bases 6 et de hauteurs d₁, d₂, d₃ ; leurs aires 6d₁ ÷ 2, 6d₂ ÷ 2, 6d₃ ÷ 2 font l’aire totale 6h ÷ 2.','The sum of the three distances is the height h = 6 × √3 ÷ 2 = 3√3 ≈ 5.196. So the third distance is 3√3 − 1 − 2 ≈ 2.20. Why the sum is h: joining P to the vertices cuts the triangle into three triangles with bases 6 and heights d₁, d₂, d₃; their areas 6d₁ ÷ 2, 6d₂ ÷ 2, 6d₃ ÷ 2 make the whole area 6h ÷ 2.'),
    history:pair('Viviani · XVIIe siècle','Viviani · 17th century'),
    story:pair('Le résultat porte le nom de Vincenzo Viviani (1622-1703), élève de Galilée, qui l’a énoncé au XVIIe siècle. La preuve par les aires tient en une ligne, mais elle cache une idée qui sert partout : découper une figure pour comparer des aires.','The result is named after Vincenzo Viviani (1622-1703), a pupil of Galileo, who stated it in the 17th century. The proof by areas fits in one line, but it hides an idea used everywhere: cut a figure up to compare areas.'),
    source:'https://mathworld.wolfram.com/VivianisTheorem.html',sourceLabel:pair('Viviani’s Theorem · MathWorld (anglais)','Viviani’s Theorem · MathWorld'),
    reasoning:{conjecture:pair('Dans tout triangle, la somme des distances d’un point intérieur aux trois côtés est la même partout.','In every triangle, the sum of the distances from an inside point to the three sides is the same everywhere.'),
      proof:pair('Vrai pour un triangle équilatéral (théorème de Viviani), faux en général. Les aires donnent a·d₁ + b·d₂ + c·d₃ = 2 × aire dans tout triangle ; on ne peut diviser par un même nombre que si a = b = c. Dans un triangle quelconque, la somme vaut la hauteur issue de A quand P est en A, et une autre hauteur quand P est en B : elle change.','True for an equilateral triangle (Viviani’s theorem), false in general. Areas give a·d₁ + b·d₂ + c·d₃ = 2 × area in every triangle; we can divide by one same number only when a = b = c. In any triangle, the sum is the height from A when P is at A, and another height when P is at B: it changes.'),
      transfer:pair('À chercher : dans un carré de côté 4, que vaut la somme des distances d’un point intérieur aux quatre côtés ? (8 : deux côtés opposés donnent toujours 4.)','To find: in a square of side 4, what is the sum of the distances from an inside point to the four sides? (8: two opposite sides always give 4.)')},
    links:['#chapter/seconde-12','#chapter/seconde-13']},
  {...base,id:'dandelin',symbol:'◎',group:pair('Formes & mouvement','Shapes & motion'),level:pair('Première · Terminale','Grades 11 to 12'),
    prereq:pair('Cône, sphère, plan ; tangentes à un cercle depuis un point.','Cone, sphere, plane; tangents to a circle from a point.'),
    title:pair('Les sphères de Dandelin','Dandelin’s spheres'),short:pair('D’où viennent les foyers d’une ellipse ?','Where do the foci of an ellipse come from?'),
    intro:pair('Coupe un cône par un plan incliné : la trace est une ellipse. Glisse deux sphères dans le cône, l’une au-dessus du plan, l’autre en dessous, jusqu’à ce qu’elles touchent le plan. Où le touchent-elles ?','Cut a cone with a tilted plane: the cut is an ellipse. Slide two spheres into the cone, one above the plane and one below, until they touch the plane. Where do they touch it?'),
    steps:[pair('Réponds à la question, puis promène P sur l’ellipse et lis PF₁, PF₂ et leur somme.','Answer the question, then move P along the ellipse and read PF₁, PF₂ and their sum.'),pair('Incline le plan : les sphères et les foyers bougent, la somme change avec l’ellipse, mais reste la même pour tous les points d’une même ellipse.','Tilt the plane: the spheres and the foci move, the sum changes with the ellipse, but stays the same for all points of one ellipse.'),pair('Compare la somme avec T₁T₂ et avec le grand axe, puis ouvre l’explication.','Compare the sum with T₁T₂ and with the major axis, then open the explanation.')],
    quiz:pair('Deux punaises à 6 cm l’une de l’autre, une ficelle de 10 cm attachée aux deux, un crayon qui tend la ficelle : quelle est la demi-largeur de l’ellipse tracée, en cm ?','Two pins 6 cm apart, a 10 cm string tied to both, a pencil keeping it tight: what is the half-width of the ellipse drawn, in cm?'),answer:4,
    explain:pair('4 cm. Pour tout point de l’ellipse, PF₁ + PF₂ = 10. Au bout du grand axe, cela donne un grand axe de 10, donc a = 5 ; les punaises sont à c = 3 du centre. Au sommet de la petite largeur, P est à égale distance des deux punaises : PF₁ = PF₂ = 5, et Pythagore donne b = √(5² − 3²) = 4.','4 cm. For every point of the ellipse, PF₁ + PF₂ = 10. At the end of the major axis this gives a major axis of 10, so a = 5; the pins are c = 3 from the centre. At the top of the short width, P is equally far from both pins: PF₁ = PF₂ = 5, and Pythagoras gives b = √(5² − 3²) = 4.'),
    history:pair('Dandelin · 1822','Dandelin · 1822'),
    story:pair('Germinal Pierre Dandelin, mathématicien belge, publie cette preuve en 1822. Les Grecs avaient étudié les coniques comme sections d’un cône (Apollonius), et les foyers apparaissaient dans les propriétés planes de l’ellipse ; les sphères montrent d’un coup pourquoi la section d’un cône a la propriété des foyers.','Germinal Pierre Dandelin, a Belgian mathematician, published this proof in 1822. The Greeks had studied conics as sections of a cone (Apollonius), and the foci appeared in the plane properties of the ellipse; the spheres show at once why the section of a cone has the focal property.'),
    source:'https://mathworld.wolfram.com/DandelinSpheres.html',sourceLabel:pair('Dandelin Spheres · MathWorld (anglais)','Dandelin Spheres · MathWorld'),
    reasoning:{conjecture:pair('La section d’un cône par un plan qui ne coupe qu’une nappe est une ellipse, de foyers les points de contact des deux sphères.','The section of a cone by a plane that cuts only one nappe is an ellipse, with foci at the points where the two spheres touch it.'),
      proof:pair('Vrai (théorème de Dandelin). Les deux tangentes menées d’un point à une sphère ont la même longueur, donc PF₁ = PT₁ et PF₂ = PT₂, et PF₁ + PF₂ = T₁T₂, la portion de génératrice entre les deux cercles de contact, la même pour toutes les génératrices. L’exposition le vérifie par le calcul en 60 points pour plusieurs cônes et plans.','True (Dandelin’s theorem). The two tangents from a point to a sphere have the same length, so PF₁ = PT₁ and PF₂ = PT₂, and PF₁ + PF₂ = T₁T₂, the piece of generator between the two circles of contact, the same on every generator. The exhibit checks it by computation at 60 points for several cones and planes.'),
      transfer:pair('À chercher : si le plan est parallèle à une génératrice, la section est une parabole et il ne reste qu’une sphère. Que devient alors la propriété des foyers ? (le foyer, et la droite où le plan coupe le plan du cercle de contact : la directrice.)','To find: if the plane is parallel to a generator, the section is a parabola and only one sphere remains. What becomes of the focal property then? (the focus, and the line where the plane meets the plane of the circle of contact: the directrix.)')},
    links:['#gallery/polyhedra','#chapter/terminale-02']},
  {...base,id:'cavalieri',symbol:'⌓',group:pair('Formes & mouvement','Shapes & motion'),level:pair('Première · Terminale','Grades 11 to 12'),
    prereq:pair('Aire d’un disque, volumes du cylindre et du cône, Pythagore.','Area of a disc, volumes of the cylinder and the cone, Pythagoras.'),
    title:pair('Le principe de Cavalieri','Cavalieri’s principle'),short:pair('Des solides différents, un même volume','Different solids, the same volume'),
    intro:pair('Une demi-boule et un cylindre creusé d’un cône n’ont pas du tout la même forme. Coupe-les par un même plan horizontal, à toutes les hauteurs : que remarques-tu ?','A hemisphere and a cylinder with a cone dug out do not look alike at all. Cut them with one horizontal plane, at every height: what do you notice?'),
    steps:[pair('Commence par l’échauffement : pousse une pile de cartes et regarde ce qui change, et ce qui ne change pas.','Start with the warm-up: push a stack of cards and see what changes, and what does not.'),pair('Réponds à la question, puis promène le plan de coupe sur toute la hauteur en lisant les deux sections.','Answer the question, then move the cutting plane over the whole height while reading the two sections.'),pair('Ouvre l’explication : le calcul montre l’égalité des sections à toutes les hauteurs, pas seulement à celles essayées.','Open the explanation: the computation shows the sections are equal at every height, not only at those tried.')],
    quiz:pair('Un cylindre de rayon 3 et de hauteur 3 est creusé d’un cône de même base, sommet en bas. Son volume est k × π : que vaut k ?','A cylinder of radius 3 and height 3 has a cone with the same base dug out, apex at the bottom. Its volume is k × π: what is k?'),answer:18,
    explain:pair('k = 18. Cylindre : π × 3² × 3 = 27π ; cône : 27π / 3 = 9π ; il reste 18π. C’est le volume d’une demi-boule de rayon 3, 2π × 3³ / 3 = 18π, comme le principe de Cavalieri l’annonce.','k = 18. Cylinder: π × 3² × 3 = 27π; cone: 27π / 3 = 9π; 18π is left. It is the volume of a hemisphere of radius 3, 2π × 3³ / 3 = 18π, as Cavalieri’s principle says.'),
    history:pair('Cavalieri · 1635 ; Archimède · IIIe siècle av. J.-C.','Cavalieri · 1635; Archimedes · 3rd century BC'),
    story:pair('Bonaventura Cavalieri, élève de Galilée, publie en 1635 sa méthode des « indivisibles » : comparer deux solides tranche par tranche. Archimède connaissait déjà le volume de la boule ; il le tenait pour sa plus belle découverte et fit graver une sphère dans un cylindre sur sa tombe. Le calcul intégral donnera plus tard un fondement solide à ces tranches.','Bonaventura Cavalieri, a pupil of Galileo, published his method of “indivisibles” in 1635: compare two solids slice by slice. Archimedes already knew the volume of the ball; he held it as his finest discovery and had a sphere in a cylinder carved on his tomb. Integral calculus later gave these slices a solid foundation.'),
    source:'https://mathworld.wolfram.com/CavalierisPrinciple.html',sourceLabel:pair('Cavalieri’s Principle · MathWorld (anglais)','Cavalieri’s Principle · MathWorld'),
    reasoning:{conjecture:pair('Deux solides de même hauteur dont les sections ont la même aire à toutes les hauteurs ont le même volume.','Two solids of the same height whose sections have the same area at every height have the same volume.'),
      proof:pair('Vrai : c’est le principe de Cavalieri, qui revient à V = ∫ S(z) dz avec la même fonction S. Ici S(z) = π(R² − z²) pour la demi-boule (Pythagore) et πR² − πz² pour le cylindre creusé (le cône a le rayon z à la hauteur z) : la même fonction pour tout z, d’où V = πR³ − πR³/3 = 2πR³/3. Comparer quelques hauteurs ne suffirait pas ; c’est l’égalité pour tout z qui compte.','True: this is Cavalieri’s principle, which amounts to V = ∫ S(z) dz with the same function S. Here S(z) = π(R² − z²) for the hemisphere (Pythagoras) and πR² − πz² for the dug-out cylinder (the cone has radius z at height z): the same function for every z, hence V = πR³ − πR³/3 = 2πR³/3. Comparing a few heights would not be enough; the equality for every z is what counts.'),
      transfer:pair('À chercher : une boule de rayon R percée d’un trou cylindrique laisse un anneau de hauteur h. Montre que ses sections ont la même aire que celles d’une boule de diamètre h, et déduis-en V = πh³/6.','To find: a ball of radius R drilled through by a cylindrical hole leaves a ring of height h. Show that its sections have the same area as those of a ball of diameter h, and deduce V = πh³/6.')},
    links:['#intuition','#gallery/napkin-ring','#chapter/terminale-11','#chapter/terminale-02']},
  {...base,id:'rupert',symbol:'⬡',group:pair('Formes & mouvement','Shapes & motion'),level:pair('Seconde · Terminale','Grades 10 to 12'),
    prereq:pair('Cube, projection orthogonale, aire d’un carré.','Cube, orthogonal projection, area of a square.'),
    title:pair('Le cube du prince Rupert','Prince Rupert’s cube'),short:pair('Un cube passe à travers un cube de même taille','A cube passes through a cube of the same size'),
    intro:pair('Perce un tunnel droit dans un cube. Un cube identique peut-il le traverser, sans que le premier se casse en deux ? Regarde les ombres : tout se joue dans le plan.','Drill a straight tunnel through a cube. Can an identical cube go through it without the first breaking in two? Look at the shadows: everything happens in the plane.'),
    steps:[pair('Réponds à la question, puis glisse sur la figure pour tourner la pièce : quand son ombre tient dans celle du bloc avec de la place, s dépasse 1.','Answer the question, then drag on the figure to turn the piece: when its shadow fits in the block’s with room, s goes above 1.'),pair('Demande un passage vérifié, puis regarde la pièce traverser le bloc dans la vue « Le passage ».','Ask for a verified passage, then watch the piece go through the block in the “passage” view.'),pair('Essaie les autres solides de Platon, puis le rhombicosidodécaèdre : la recherche n’y dépasse jamais s = 1, et cela ne prouve rien à lui seul.','Try the other Platonic solids, then the rhombicosidodecahedron: the search never goes above s = 1 there, and that alone proves nothing.')],
    quiz:pair('Un carré de côté 1 est tourné de 45°. Quel est le côté du plus grand carré, posé droit, qui tient à l’intérieur ? (arrondi à 0,01)','A square of side 1 is turned by 45°. What is the side of the largest upright square that fits inside it? (to 0.01)'),answer:0.71,tolerance:0.01,
    explain:pair('√2/2 ≈ 0,71. Le carré tourné a ses sommets sur les axes, à la distance √2/2 du centre ; ses côtés sont les droites |x| + |y| = √2/2. Un carré droit de demi-côté h y tient si h + h ≤ √2/2, soit un côté 2h ≤ √2/2. C’est le même calcul que l’exposition fait pour chaque côté de l’ombre du bloc.','√2/2 ≈ 0.71. The turned square has its vertices on the axes, at distance √2/2 from the centre; its sides are the lines |x| + |y| = √2/2. An upright square of half-side h fits if h + h ≤ √2/2, so a side 2h ≤ √2/2. It is the same computation the exhibit makes for each side of the block’s shadow.'),
    history:pair('Rupert · XVIIe siècle ; Noperthèdre · 2025','Rupert · 17th century; Noperthedron · 2025'),
    story:pair('Le prince Rupert du Rhin aurait parié qu’un cube pouvait passer par un trou percé dans un cube de même taille. John Wallis montre que c’est possible ; Pieter Nieuwland trouve au XVIIIe siècle le plus grand cube qui passe, de côté 3√2/4. En 2017, Jerrard, Wetzel et Yuan demandent si tout polyèdre convexe a cette propriété. En 2025, Steininger et Yurkevich répondent non avec le Noperthèdre, preuve assistée par ordinateur ; en 2026 sont annoncés le Septopert, à 7 sommets, et le rhombicosidodécaèdre.','Prince Rupert of the Rhine is said to have bet that a cube could pass through a hole drilled in a cube of the same size. John Wallis showed it is possible; in the 18th century Pieter Nieuwland found the largest cube that passes, of side 3√2/4. In 2017 Jerrard, Wetzel and Yuan asked whether every convex polyhedron has this property. In 2025 Steininger and Yurkevich answered no with the Noperthedron, a computer-assisted proof; in 2026 the Septopert, with 7 vertices, and the rhombicosidodecahedron were announced.'),
    source:'https://mathworld.wolfram.com/PrinceRupertsCube.html',sourceLabel:pair('Prince Rupert’s Cube · MathWorld (anglais)','Prince Rupert’s Cube · MathWorld'),
    reasoning:{conjecture:pair('Tout polyèdre convexe peut passer par un tunnel droit percé dans une copie de lui-même.','Every convex polyhedron can pass through a straight tunnel drilled in a copy of itself.'),
      proof:pair('Faux. C’est vrai pour le cube (jusqu’à 3√2/4) et pour les cinq solides de Platon, dont l’exposition montre des passages vérifiés par deux calculs. Mais Steininger et Yurkevich (2025) ont prouvé, avec l’aide d’un ordinateur, que le Noperthèdre n’a aucun passage. Ne pas trouver de passage par une recherche n’aurait rien prouvé : il faut un argument qui couvre toutes les positions.','False. It is true for the cube (up to 3√2/4) and for the five Platonic solids, for which the exhibit shows passages checked by two computations. But Steininger and Yurkevich (2025) proved, with the help of a computer, that the Noperthedron has no passage. Failing to find a passage by a search would have proved nothing: an argument covering every position is needed.'),
      transfer:pair('À chercher : une boule peut-elle passer par un trou percé dans une boule de même rayon ? (non : toutes ses ombres sont des disques de même rayon, aucun ne tient dans un autre avec de la place.)','To find: can a ball pass through a hole drilled in a ball of the same radius? (no: all its shadows are discs of the same radius, none fits inside another with room.)')},
    links:['#intuition','#gallery/platonic','#gallery/polyhedra','#chapter/terminale-02']},
  {...base,id:'star-polyhedra',symbol:'✶',group:pair('Formes & mouvement','Shapes & motion'),level:pair('Première · Terminale','Grades 11 to 12'),
    prereq:pair('Polygones réguliers, plans dans l’espace, la relation d’Euler V − E + F = 2.','Regular polygons, planes in space, Euler’s relation V − E + F = 2.'),
    title:pair('Les solides étoilés de Kepler et Poinsot','The star solids of Kepler and Poinsot'),short:pair('Prolonger les faces d’un dodécaèdre','Extending the faces of a dodecahedron'),
    intro:pair('Garde les plans des faces d’un dodécaèdre et prolonge les faces jusqu’à ce qu’elles se recoupent. Il en sort des solides étoilés aux faces régulières, qui se traversent. Sont-ils encore des polyèdres « comme les autres » ?','Keep the face planes of a dodecahedron and extend the faces until they meet again. Star solids with regular faces come out, passing through each other. Are they still polyhedra “like the others”?'),
    steps:[pair('Réponds à la question sur V − E + F, puis regarde les trois étapes étoilées du dodécaèdre.','Answer the question about V − E + F, then look at the three star stages of the dodecahedron.'),pair('Suis une face dans le schéma de son plan : à chaque étape elle s’étend jusqu’aux droites suivantes.','Follow one face in the diagram of its plane: at each stage it reaches the next lines.'),pair('Passe aux faces de l’icosaèdre : le grand icosaèdre.','Switch to the faces of the icosahedron: the great icosahedron.')],
    quiz:pair('Le petit dodécaèdre étoilé a 12 sommets, 30 arêtes et 12 faces en pentagramme. Que vaut V − E + F ?','The small stellated dodecahedron has 12 vertices, 30 edges and 12 pentagram faces. What is V − E + F?'),answer:-6,
    explain:pair('12 − 30 + 12 = −6. La relation d’Euler V − E + F = 2 vaut pour une surface comme une sphère ; en comptant chaque pentagramme comme une seule face, la surface de ce solide n’en est pas une.','12 − 30 + 12 = −6. Euler’s relation V − E + F = 2 holds for a surface like a sphere; counting each pentagram as one face, the surface of this solid is not one.'),
    history:pair('Kepler · 1619 ; Poinsot · 1809 ; Cauchy · 1813','Kepler · 1619; Poinsot · 1809; Cauchy · 1813'),
    story:pair('Kepler décrit les deux dodécaèdres étoilés dans Harmonices Mundi (1619). Louis Poinsot redécouvre ces deux-là et trouve le grand dodécaèdre et le grand icosaèdre en 1809. Augustin Cauchy prouve en 1813, en partant justement de la stellation, qu’il n’existe pas d’autre polyèdre régulier étoilé.','Kepler described the two stellated dodecahedra in Harmonices Mundi (1619). Louis Poinsot rediscovered those two and found the great dodecahedron and the great icosahedron in 1809. Augustin Cauchy proved in 1813, starting precisely from stellation, that there is no other regular star polyhedron.'),
    source:'https://mathworld.wolfram.com/Kepler-PoinsotSolid.html',sourceLabel:pair('Kepler-Poinsot Solid · MathWorld (anglais)','Kepler-Poinsot Solid · MathWorld'),
    reasoning:{conjecture:pair('V − E + F = 2 pour tout polyèdre aux faces régulières.','V − E + F = 2 for every polyhedron with regular faces.'),
      proof:pair('Faux : le petit dodécaèdre étoilé et le grand dodécaèdre donnent 12 − 30 + 12 = −6. La relation d’Euler demande une surface déformable en sphère (un polyèdre convexe en a une) ; les faces de ces solides se traversent et leur surface n’en est pas une.','False: the small stellated dodecahedron and the great dodecahedron give 12 − 30 + 12 = −6. Euler’s relation needs a surface that can be deformed into a sphere (a convex polyhedron has one); the faces of these solids pass through each other and their surface is not one.'),
      transfer:pair('À chercher : le grand dodécaèdre étoilé a 20 sommets, 30 arêtes et 12 faces. Que vaut V − E + F ? (2.)','To find: the great stellated dodecahedron has 20 vertices, 30 edges and 12 faces. What is V − E + F? (2.)')},
    links:['#gallery/polyhedra','#gallery/wythoff','#gallery/platonic']},
  {...base,id:'wythoff',symbol:'◬',group:pair('Formes & mouvement','Shapes & motion'),level:pair('Première · Terminale','Grades 11 to 12'),
    prereq:pair('Symétrie par rapport à un plan, polygones réguliers, solides de Platon.','Reflection in a plane, regular polygons, Platonic solids.'),
    title:pair('Le triangle de Wythoff','The Wythoff triangle'),short:pair('Tous les solides d’Archimède dans un triangle','Every Archimedean solid in one triangle'),
    intro:pair('Trois miroirs forment un triangle sur la sphère. Place un point dans le triangle : ses reflets sont les sommets d’un solide. Où le mettre pour que toutes les arêtes soient égales ?','Three mirrors form a triangle on the sphere. Put a point in the triangle: its reflections are the vertices of a solid. Where should it go for every edge to be equal?'),
    steps:[pair('Réponds à la question, puis glisse le point dans le triangle et lis les arêtes.','Answer the question, then drag the point in the triangle and read the edges.'),pair('Essaie les sept points marqués pour chaque symétrie, puis la torsion.','Try the seven marked points for each symmetry, then the twist.'),pair('Montre le dual : les solides de Catalan. Termine par le défi de classement.','Show the dual: the Catalan solids. Finish with the classification challenge.')],
    quiz:pair('Le point est au centre du triangle du cube (les trois distances égales). Combien de sommets a le solide obtenu ?','The point is at the centre of the cube’s triangle (all three distances equal). How many vertices does the solid have?'),answer:48,
    explain:pair('48 : le point a un reflet dans chacun des 48 triangles du cube (24 rotations, chacune avec ou sans réflexion). C’est le grand rhombicuboctaèdre, avec 12 carrés, 8 hexagones et 6 octogones.','48: the point has one reflection in each of the cube’s 48 triangles (24 rotations, each with or without a reflection). It is the truncated cuboctahedron, with 12 squares, 8 hexagons and 6 octagons.'),
    history:pair('Wythoff · 1918 ; Coxeter · 1954','Wythoff · 1918; Coxeter · 1954'),
    story:pair('Willem Abraham Wythoff décrit la construction en 1918. H. S. M. Coxeter et ses collaborateurs l’utilisent en 1954 pour dresser la liste complète des polyèdres uniformes. Les 13 solides d’Archimède étaient connus d’Archimède selon Pappus ; Kepler les redécrit en 1619.','Willem Abraham Wythoff described the construction in 1918. H. S. M. Coxeter and his co-authors used it in 1954 to list all uniform polyhedra. The 13 Archimedean solids were known to Archimedes according to Pappus; Kepler described them again in 1619.'),
    source:'https://mathworld.wolfram.com/WythoffSymbol.html',sourceLabel:pair('Wythoff Symbol · MathWorld (anglais)','Wythoff Symbol · MathWorld'),
    reasoning:{conjecture:pair('Un solide convexe dont toutes les faces sont régulières a tous ses sommets pareils.','A convex solid whose faces are all regular has all its vertices alike.'),
      proof:pair('Faux : la pyramide à base carrée, aux arêtes égales, a des faces régulières mais un sommet entouré de quatre triangles et quatre sommets entourés de deux triangles et d’un carré. C’est un solide de Johnson ; il y en a 92.','False: the square pyramid with equal edges has regular faces but one vertex surrounded by four triangles and four vertices surrounded by two triangles and a square. It is a Johnson solid; there are 92 of them.'),
      transfer:pair('À chercher : combien de sommets pour le point au milieu du côté opposé au coin d’ordre 4, dans la symétrie du cube ? (12 : le cuboctaèdre.)','To find: how many vertices for the point at the midpoint of the side opposite the order 4 corner, in the cube’s symmetry? (12: the cuboctahedron.)')},
    links:['#gallery/polyhedra','#gallery/star-polyhedra','#gallery/platonic','#chapter/terminale-02']},
  {...base,id:'basins',symbol:'✺',group:pair('Formes & mouvement','Shapes & motion'),level:pair('Terminale · au-delà','Grade 12 · beyond'),
    prereq:pair('Nombres complexes (forme algébrique, module), suites définies par récurrence.','Complex numbers (algebraic form, modulus), sequences defined by recurrence.'),
    title:pair('Multibrot et bassins de Newton','Multibrot and Newton basins'),short:pair('Itérer dans le plan complexe','Iterating in the complex plane'),
    intro:pair('Répète z ↦ zᵈ + c, ou la méthode de Newton pour résoudre une équation, et colorie chaque point selon ce que devient sa suite. Des frontières d’une complexité infinie apparaissent.','Repeat z ↦ zᵈ + c, or Newton’s method for solving an equation, and colour each point by what its sequence does. Boundaries of infinite complexity appear.'),
    steps:[pair('Réponds à la question sur la symétrie, puis change la puissance d.','Answer the question about symmetry, then change the power d.'),pair('Touche l’image : le point choisi, sa sortie ou son chemin vers une racine. Zoome autour de lui.','Touch the image: the chosen point, its escape or its path to a root. Zoom around it.'),pair('Passe à Newton et essaie z³ − 2z + 2 : la méthode échoue sur toute une région.','Switch to Newton and try z³ − 2z + 2: the method fails on a whole region.')],
    quiz:pair('Pour z ↦ z⁶ + c, combien de copies identiques de la figure tournent autour de 0 ?','For z ↦ z⁶ + c, how many identical copies of the figure turn around 0?'),answer:5,
    explain:pair('5 = 6 − 1 : si ω⁵ = 1, remplacer c par ωc multiplie toute la suite par ω, sans changer le module de ses termes.','5 = 6 − 1: if ω⁵ = 1, replacing c by ωc multiplies the whole sequence by ω, without changing the modulus of its terms.'),
    history:pair('Fatou, Julia · 1918 ; Newton, Cayley · 1879','Fatou, Julia · 1918; Newton, Cayley · 1879'),
    story:pair('Arthur Cayley demande en 1879 vers quelle racine converge la méthode de Newton dans le plan complexe : facile pour deux racines, il bute sur trois. Pierre Fatou et Gaston Julia étudient vers 1918 l’itération des fractions rationnelles ; les ordinateurs révèlent leurs frontières dans les années 1980.','Arthur Cayley asked in 1879 towards which root Newton’s method converges in the complex plane: easy for two roots, he got stuck on three. Pierre Fatou and Gaston Julia studied the iteration of rational maps around 1918; computers revealed their boundaries in the 1980s.'),
    source:'https://mathworld.wolfram.com/NewtonsMethod.html',sourceLabel:pair('Newton’s Method · MathWorld (anglais)','Newton’s Method · MathWorld'),
    reasoning:{conjecture:pair('Partie d’un point au hasard, la méthode de Newton finit toujours sur une racine.','Started from a random point, Newton’s method always ends on a root.'),
      proof:pair('Faux : pour z³ − 2z + 2, on a N(0) = 1 et N(1) = 0, et la dérivée de la méthode est nulle en 0 ; tous les points proches de 0 tombent dans ce cycle et n’atteignent jamais une racine. L’exposition le vérifie sur 200 points d’un disque autour de 0.','False: for z³ − 2z + 2, N(0) = 1 and N(1) = 0, and the derivative of the method is zero at 0; all points near 0 fall into this cycle and never reach a root. The exhibit checks it on 200 points of a disc around 0.'),
      transfer:pair('À chercher : pour z² − 1, où est la frontière entre les deux bassins ? (la droite des imaginaires purs, Re z = 0.)','To find: for z² − 1, where is the boundary between the two basins? (the imaginary axis, Re z = 0.)')},
    links:['#fractals','#gallery/mandelbrot','#gallery/escape-3d']},
  {...base,id:'apollonian',symbol:'◍',group:pair('Formes & mouvement','Shapes & motion'),level:pair('Première · Terminale','Grades 11 to 12'),
    prereq:pair('Cercles tangents, équation du second degré, somme et produit des racines.','Tangent circles, quadratic equations, sum and product of the roots.'),
    title:pair('La baderne d’Apollonius','The Apollonian gasket'),short:pair('Des cercles dans les espaces entre des cercles','Circles in the gaps between circles'),
    intro:pair('Dans chaque espace entre trois cercles qui se touchent, place le cercle qui touche les trois, et recommence. Les courbures, inverses des rayons, partent de 2, 2 et 3. Restent-elles des nombres entiers ?','In every gap between three touching circles, place the circle that touches all three, and repeat. The curvatures, one over the radii, start from 2, 2 and 3. Do they stay whole numbers?'),
    steps:[pair('Réponds à la question, puis construis les étapes en lisant les courbures.','Answer the question, then build the stages while reading the curvatures.'),pair('Touche un cercle : la relation de Descartes avec les trois cercles qu’il touche.','Touch a circle: Descartes’ relation with the three circles it touches.'),pair('Suis la part du disque couverte sur le graphique.','Follow the share of the disc covered on the plot.')],
    quiz:pair('Trois cercles de courbures −1, 2 et 2 se touchent ; un cercle de courbure 3 les touche tous les trois. Quelle est la courbure de l’autre cercle qui les touche ?','Three circles of curvatures −1, 2 and 2 touch; a circle of curvature 3 touches all three. What is the curvature of the other circle touching them?'),answer:3,
    explain:pair('3 : les deux solutions vérifient k + k′ = 2(−1 + 2 + 2) = 6, donc k′ = 6 − 3 = 3. C’est le cercle symétrique, sous le diamètre.','3: the two solutions satisfy k + k′ = 2(−1 + 2 + 2) = 6, so k′ = 6 − 3 = 3. It is the mirror circle, below the diameter.'),
    history:pair('Apollonius · IIIe siècle av. J.-C. ; Descartes · 1643','Apollonius · 3rd century BC; Descartes · 1643'),
    story:pair('Apollonius de Perge cherche les cercles tangents à trois cercles donnés. Descartes énonce la relation des courbures dans une lettre à la princesse Élisabeth de Bohême en 1643 ; Frederick Soddy la redécouvre en 1936 et la publie en poème dans Nature.','Apollonius of Perga looked for the circles tangent to three given circles. Descartes stated the relation between curvatures in a letter to Princess Elisabeth of Bohemia in 1643; Frederick Soddy rediscovered it in 1936 and published it as a poem in Nature.'),
    source:'https://mathworld.wolfram.com/ApollonianGasket.html',sourceLabel:pair('Apollonian Gasket · MathWorld (anglais)','Apollonian Gasket · MathWorld'),
    reasoning:{conjecture:pair('Partant de courbures entières, tous les cercles de la baderne ont une courbure entière.','Starting from whole curvatures, every circle of the gasket has a whole curvature.'),
      proof:pair('Vrai. Trois cercles fixés, l’équation de Descartes en k₄ est du second degré ; ses deux solutions ont pour somme 2(k₁ + k₂ + k₃). Le nouveau cercle a donc la courbure 2(k₁ + k₂ + k₃) − k₄, un entier si les quatre autres le sont.','True. With three circles fixed, Descartes’ equation in k₄ is quadratic; its two solutions add up to 2(k₁ + k₂ + k₃). So the new circle has curvature 2(k₁ + k₂ + k₃) − k₄, a whole number if the other four are.'),
      transfer:pair('À chercher : quelle est la courbure du cercle placé dans l’espace entre les cercles 2, 2 et 3 ? (2(2 + 2 + 3) − (−1) = 15.)','To find: what is the curvature of the circle placed in the gap between the circles 2, 2 and 3? (2(2 + 2 + 3) − (−1) = 15.)')},
    links:['#fractals','#gallery/self-similar']},
  {...base,id:'escape-3d',symbol:'❂',group:pair('Formes & mouvement','Shapes & motion'),level:pair('Terminale · au-delà','Grade 12 · beyond'),
    prereq:pair('Nombres complexes, coordonnées sphériques (vues sur la page), l’ensemble de Mandelbrot.','Complex numbers, spherical coordinates (seen on the page), the Mandelbrot set.'),
    title:pair('Mandelbulb, Mandelbox et Julia en 3D','Mandelbulb, Mandelbox and 3D Julia'),short:pair('Des fractales d’itération dans l’espace','Iteration fractals in space'),
    intro:pair('Peut-on faire « le Mandelbrot en 3D » ? Trois réponses : une formule choisie, une suite de replis, et la tranche d’un ensemble de dimension 4.','Can one make “the Mandelbrot set in 3D”? Three answers: a chosen formula, a sequence of folds, and the slice of a four-dimensional set.'),
    steps:[pair('Réponds à la question, puis fais tourner la Mandelbulb et change sa puissance.','Answer the question, then turn the Mandelbulb and change its power.'),pair('Passe à la Mandelbox et change son échelle.','Switch to the Mandelbox and change its scale.'),pair('Déplace la tranche w de l’ensemble de Julia quaternionique.','Move the slice w of the quaternion Julia set.')],
    quiz:pair('La Mandelbulb de puissance n a combien de copies identiques autour de l’axe vertical, pour n = 9 ?','How many identical copies around the vertical axis does the Mandelbulb of power n have, for n = 9?'),answer:8,
    explain:pair('8 = n − 1 : tourner le point de départ d’un angle α autour de l’axe ajoute α à l’angle φ, multiplié par n à chaque étape ; la figure revient sur elle-même quand (n − 1)α est un multiple de 2π.','8 = n − 1: turning the starting point by an angle α about the axis adds α to the angle φ, multiplied by n at each step; the figure comes back onto itself when (n − 1)α is a multiple of 2π.'),
    history:pair('Frobenius · 1878 ; White et Nylander · 2009 ; Lowe · 2010','Frobenius · 1878; White and Nylander · 2009; Lowe · 2010'),
    story:pair('Hamilton cherche pendant des années des nombres à trois dimensions et trouve en 1843 les quaternions, de dimension 4. Frobenius prouve en 1878 qu’il n’y a pas d’autre choix. Daniel White et Paul Nylander proposent la Mandelbulb en 2009, Tom Lowe la Mandelbox en 2010 : des formules choisies, non des théorèmes.','Hamilton looked for years for three-dimensional numbers and found the quaternions, of dimension 4, in 1843. Frobenius proved in 1878 that there is no other choice. Daniel White and Paul Nylander proposed the Mandelbulb in 2009, Tom Lowe the Mandelbox in 2010: chosen formulas, not theorems.'),
    source:'https://mathworld.wolfram.com/Mandelbulb.html',sourceLabel:pair('Mandelbulb · MathWorld (anglais)','Mandelbulb · MathWorld'),
    reasoning:{conjecture:pair('Il existe des nombres à trois dimensions qui se multiplient et se divisent comme les complexes.','There are three-dimensional numbers that multiply and divide like complex numbers.'),
      proof:pair('Faux (Frobenius, 1878) : les seules algèbres réelles associatives où l’on peut diviser sont les réels, les complexes et les quaternions, de dimensions 1, 2 et 4. La Mandelbulb imite donc les complexes par une formule choisie.','False (Frobenius, 1878): the only associative real algebras where one can divide are the reals, the complex numbers and the quaternions, of dimensions 1, 2 and 4. So the Mandelbulb imitates complex numbers with a chosen formula.'),
      transfer:pair('À chercher : pour les quaternions, i j = k mais j i = −k. Que vaut i² ? (−1, comme j² et k².)','To find: for quaternions, i j = k but j i = −k. What is i²? (−1, like j² and k².)')},
    links:['#fractals','#gallery/mandelbrot','#gallery/basins']},
];
